const root=document.querySelector('#journal-root'),escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=new Intl.NumberFormat('en-AU',{maximumFractionDigits:2}),kg=v=>Number.isFinite(v)?nf.format(v):'—',signed=v=>Number.isFinite(v)?(v>0?'+':'')+nf.format(v):'—';
const day=value=>new Date(value+'T12:00:00Z').toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}),dateMs=d=>Date.parse(d+'T12:00:00Z');
const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg>',logo='<svg viewBox="0 0 36 36" aria-hidden="true"><path d="m3 27 9-18 6 12 6-12 9 18M8 18h20"/></svg>';
let data,windowChoice='90',selection=0,chart,preview,busy=false,animation,motion=true;
try{motion=localStorage.getItem('mfa-visual-motion')!=='off';}catch{}
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
async function api(url,options){const response=await fetch(url,options);let value;try{value=await response.json();}catch{throw new Error('The local service could not respond. Try again.');}if(!response.ok)throw new Error(value.error||'The request could not finish.');return value;}
function graph(){const points=data.points;if(!points.length){chart=null;return '<div class="jr-empty"><span class="tr-eyebrow">Your first reading starts the line</span><h2>Bring your history<br>into the picture.</h2><p>Import a MASS backup to see your weight readings and recorded sessions here.</p></div>';}
 const values=points.map(p=>p.kg),min=Math.floor((Math.min(...values)-.3)*2)/2,max=Math.ceil((Math.max(...values)+.3)*2)/2,start=dateMs(points[0].date),end=Math.max(dateMs(data.anchor),dateMs(points.at(-1).date)),x=p=>64+(dateMs(p.date)-start)/(end-start||86400000)*790,y=value=>28+(max-value)/(max-min||1)*270;
 const path=field=>{let previous;return points.map(p=>{const value=p[field];if(value===null){previous=null;return '';}const command=previous&&dateMs(p.date)-dateMs(previous.date)<=7*86400000?'L':'M';previous=p;return `${command}${x(p).toFixed(2)},${y(value).toFixed(2)}`;}).join(' ');};chart={x,y};selection=Math.min(selection,points.length-1);const selected=points[selection];
 return `<div class="jr-chart-top"><div><span class="tr-eyebrow">Recorded body weight</span><div class="jr-selected-value"><strong id="selected-kg">${kg(selected.kg)}</strong><span>kg</span></div><p id="selected-date">${day(selected.date)} · ${selected.readings} reading${selected.readings===1?'':'s'}</p></div><div class="jr-chart-legend"><span><i></i>Daily value</span><span><i></i>7-day mean</span></div></div><div class="jr-chart-frame"><svg viewBox="0 0 900 350" aria-hidden="true"><defs><linearGradient id="weight-line" x1="0" x2="1"><stop stop-color="var(--color-highlight)"/><stop offset="1" stop-color="var(--color-accent)"/></linearGradient></defs>${[min,(min+max)/2,max].map(v=>`<path class="jr-grid" d="M64 ${y(v)}H864"/><text x="4" y="${y(v)+5}">${kg(v)}</text>`).join('')}<path class="jr-weight-line" d="${path('kg')}"/><path class="jr-mean-line" d="${path('mean7')}"/>${points.map(p=>`<circle class="jr-reading-dot" cx="${x(p)}" cy="${y(p.kg)}" r="3"/>`).join('')}<g id="chart-cursor"><path class="jr-cursor-line" d="M${x(selected)} 20V308"/><circle cx="${x(selected)}" cy="${y(selected.kg)}" r="7"/></g><text x="64" y="342">${day(points[0].date)}</text><text x="864" y="342" text-anchor="end">${day(points.at(-1).date>data.anchor?points.at(-1).date:data.anchor)}</text></svg></div><label class="jr-slider-label" for="reading-cursor">Inspect a recorded day <span id="mean-readout">${selected.mean7===null?'Mean needs 3 recorded days within 7 days':'7-day mean: '+kg(selected.mean7)+' kg'}</span></label><input id="reading-cursor" type="range" min="0" max="${points.length-1}" value="${selection}" step="1" aria-valuetext="${day(selected.date)}, ${kg(selected.kg)} kilograms"><p class="jr-chart-note">Axis follows your recorded range. Gaps longer than seven days are left open.</p>`;
}
function render(){animation?.revert();document.body.dataset.hasJournal=String(data.imports.length>0);const m=data.metrics;root.innerHTML=`<header class="tr-header"><a class="tr-brand" href="/training" aria-label="My Fitness Analyser training overview">${logo}<span>My Fitness<br><strong>Analyser</strong></span></a><nav aria-label="Main"><a href="/training">Training</a><a href="/journal" aria-current="page">Journal</a><a href="#strength">Sessions</a><a href="#measurements">Readings</a></nav><button class="tr-motion" id="motion" aria-pressed="${motion&&!reduced.matches}" aria-label="Enable motion effects">Motion <span>${motion&&!reduced.matches?'on':'off'}</span></button></header><main id="journal-main" class="jr-main"><section class="jr-heading"><div><span class="tr-eyebrow"><span class="tr-signal"></span>${data.dataset==='synthetic'?'Synthetic design preview':'Your body & strength journal'}</span><h1>THE OTHER<br><em>SIDE OF STRONG.</em></h1><p>Weight readings. Workouts logged.<br>A fuller picture of the work.</p></div><aside class="jr-source-panel"><span class="tr-eyebrow">From your MASS record</span><h2>Keep the history.<br> Build the context.</h2><p>Bring a backup across whenever you log more. Updated records stay current. Deleted records stay out.</p>${data.local?'<button id="choose-file" class="primary-button">Import MASS backup '+arrow+'</button><input type="file" id="mass-file" accept=".json,application/json" hidden><a class="text-button" href="/api/export">Export complete library '+arrow+'</a>':'<p class="jr-preview-note">Synthetic preview. Import your private history in the local app.</p>'}<p id="import-status" role="status">${data.imports.length?'Last imported '+new Date(data.imports[0].importedAt).toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'}):'No MASS file imported yet.'}</p><p id="import-error" class="tr-error" role="alert"></p></aside></section><div class="jr-window-bar"><div class="tr-window" role="group" aria-label="Journal window">${[['30','Last 30 days'],['90','Last 90 days'],['all','All imported']].map(([key,label])=>`<button data-window="${key}" aria-pressed="${windowChoice===key}">${label}</button>`).join('')}</div><span>MASS · ${m.weighIns} reading${m.weighIns===1?'':'s'} · ${m.loggedSessions} logged session${m.loggedSessions===1?'':'s'}</span></div><section class="jr-chart-section" aria-label="Weight history">${graph()}</section><section class="jr-facts" aria-label="Weight summary"><div><span>Latest daily value${m.latestDate?' · '+day(m.latestDate):''}</span><strong>${kg(m.latestKg)} <small>kg</small></strong></div><div><span>Change across selected history</span><strong>${signed(m.changeKg)} <small>kg</small></strong><p>${m.changeFrom&&m.latestDate&&m.changeKg!==null?day(m.changeFrom)+' → '+day(m.latestDate):'Two recorded days needed'}</p></div><div><span>Latest 7-day mean</span><strong>${kg(m.mean7)} <small>kg</small></strong><p>${m.mean7===null?'At least 3 recorded days within 7 days':m.meanDays+' recorded days in the window'}</p></div></section><section id="strength" class="jr-strength"><div class="tr-section-head"><div><span class="tr-eyebrow">The session log</span><h2>WORK THAT COUNTS.</h2></div><div class="jr-strength-total"><strong>${m.loggedSessions}</strong><span>recorded session${m.loggedSessions===1?'':'s'}<br>${m.recordedSessionMinutes} min · ${m.durationCoverage} with duration</span></div></div><div class="jr-strength-list">${data.sessions.length?data.sessions.map(s=>`<article class="jr-strength-row"><div class="jr-session-date"><span>${new Date(s.dateKey+'T12:00:00Z').getUTCDate()}</span><small>${new Date(s.dateKey+'T12:00:00Z').toLocaleDateString('en-AU',{month:'short',year:'numeric'})}</small></div><div><h3>${escape(s.focus)}</h3><span>MASS · ${escape(s.kind)}</span>${s.note?`<details><summary>Session note</summary><p>${escape(s.note)}</p></details>`:''}</div><strong>${s.mins===null?'—':nf.format(s.mins)}<small> min</small></strong></article>`).join(''):'<div class="jr-empty-small"><h3>No logged sessions in this window.</h3><p>Choose all imported history or bring in a newer MASS backup.</p></div>'}</div><p class="jr-section-note">Focus, time and notes come from MASS. Exercise sets, loads and repetitions are not present in this export.</p></section><section id="measurements" class="jr-measurements"><div class="tr-section-head"><div><span class="tr-eyebrow">The source readings</span><h2>EVERY ENTRY, INTACT.</h2></div><p>${m.recordedDays} recorded days · ${m.weighIns} weigh-ins</p></div><details id="reading-table"><summary>View weight readings</summary>${data.entries.length?`<div class="jr-table-wrap"><table><caption class="sr-only">MASS weight readings in the selected history</caption><thead><tr><th scope="col">Date</th><th scope="col">Weight</th><th scope="col">Note</th></tr></thead><tbody>${data.entries.map(r=>`<tr><td><button data-date="${r.dateKey}" aria-label="Inspect ${day(r.dateKey)}">${day(r.dateKey)}</button></td><td>${kg(r.kg)} kg</td><td>${r.note?escape(r.note):'—'}</td></tr>`).join('')}</tbody></table></div>`:'<p>No weight readings in this window.</p>'}</details><details class="jr-method"><summary>How the chart is calculated</summary><p>${escape(data.method)}</p><p>The selected-history change compares the first and last recorded daily values. A change in weight alone does not establish a change in fitness or body composition.</p><p>${data.tombstones} source deletion marker${data.tombstones===1?' is':'s are'} retained and excluded from the active record. Nutrition, wellness and profile goals are not displayed or analysed here.</p></details></section><footer class="tr-footer"><span>MY FITNESS ANALYSER</span><p>${escape(data.scope)}</p><a href="/training">Back to training ${arrow}</a></footer></main><dialog id="mass-review" aria-labelledby="review-title"><div class="jr-review-head"><span class="tr-eyebrow">Review before importing</span><button id="close-review" class="icon-button" aria-label="Close import review">×</button></div><div id="review-content"></div></dialog>`;bind();animate();}
function updateCursor(){const point=data.points[selection];if(!point||!chart)return;document.querySelector('#selected-kg').textContent=kg(point.kg);document.querySelector('#selected-date').textContent=day(point.date)+` · ${point.readings} reading${point.readings===1?'':'s'}`;document.querySelector('#mean-readout').textContent=point.mean7===null?'Mean needs 3 recorded days within 7 days':'7-day mean: '+kg(point.mean7)+' kg';const slider=document.querySelector('#reading-cursor');slider.value=selection;slider.setAttribute('aria-valuetext',day(point.date)+', '+kg(point.kg)+' kilograms');const cursor=document.querySelector('#chart-cursor');cursor.querySelector('path').setAttribute('d',`M${chart.x(point)} 20V308`);cursor.querySelector('circle').setAttribute('cx',chart.x(point));cursor.querySelector('circle').setAttribute('cy',chart.y(point.kg));}
async function load(window='90'){const next=await api('/api/journal?window='+window);data=next;windowChoice=window;selection=Math.max(0,data.points.length-1);render();}
function error(message){document.querySelector('#import-error').textContent=message;}
function bind(){document.querySelector('#reading-cursor')?.addEventListener('input',e=>{selection=Number(e.target.value);updateCursor();});document.querySelectorAll('[data-date]').forEach(b=>b.addEventListener('click',()=>{selection=data.points.findIndex(p=>p.date===b.dataset.date);updateCursor();document.querySelector('#reading-cursor').focus();}));document.querySelectorAll('[data-window]').forEach(b=>b.addEventListener('click',async()=>{if(b.getAttribute('aria-pressed')==='true')return;document.querySelectorAll('[data-window]').forEach(x=>x.disabled=true);try{await load(b.dataset.window);document.querySelector(`[data-window="${windowChoice}"]`).focus({preventScroll:true});}catch(e){document.querySelectorAll('[data-window]').forEach(x=>x.disabled=false);error(e.message);}}));document.querySelector('#choose-file')?.addEventListener('click',()=>document.querySelector('#mass-file').click());document.querySelector('#mass-file')?.addEventListener('change',previewFile);document.querySelector('#close-review').addEventListener('click',closeReview);document.querySelector('#mass-review').addEventListener('cancel',e=>{if(busy)e.preventDefault();else closeReview();});document.querySelector('#motion').addEventListener('click',()=>{motion=!motion;try{localStorage.setItem('mfa-visual-motion',motion?'on':'off');}catch{}animation?.revert();setMotion();});setMotion();}
function setMotion(){const enabled=motion&&!reduced.matches;document.body.dataset.motion=enabled?'on':'off';document.querySelector('#motion').setAttribute('aria-pressed',String(enabled));document.querySelector('#motion span').textContent=enabled?'on':'off';}
function animate(){if(!motion||reduced.matches||!window.gsap)return;animation=gsap.context(()=>{gsap.from('.jr-heading>div,.jr-source-panel',{opacity:0,y:20,duration:.75,stagger:.12,ease:'power3.out'});const path=document.querySelector('.jr-weight-line');if(path){const length=path.getTotalLength();gsap.fromTo(path,{strokeDasharray:length,strokeDashoffset:length},{strokeDashoffset:0,duration:1.15,delay:.1,ease:'power2.out',clearProps:'strokeDasharray,strokeDashoffset'});}});}
reduced.addEventListener('change',()=>{animation?.revert();if(data)setMotion();});
async function previewFile(e){const file=e.target.files[0];if(!file)return;e.target.value='';error('');const button=document.querySelector('#choose-file');button.disabled=true;document.querySelector('#import-status').textContent='Reading your MASS backup…';try{if(file.size>10*1024*1024)throw new Error('Choose a MASS export smaller than 10 MB.');preview=await api('/api/mass/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:await file.text()});preview.name=file.name;renderReview();document.querySelector('#mass-review').showModal();document.querySelector('#review-title').focus({preventScroll:true});document.querySelector('#import-status').textContent='Ready to review. No records saved yet.';}catch(e){error(e.message);document.querySelector('#import-status').textContent='Import did not start. Your saved data is unchanged.';}finally{button.disabled=false;}}
function renderReview(message=''){const count=kind=>preview.counts[kind];document.querySelector('#review-content').innerHTML=`<h2 id="review-title" tabindex="-1">Bring this history in?</h2><p class="jr-import-name">${escape(preview.name)}</p><p>${preview.dateRange?day(preview.dateRange[0])+' → '+day(preview.dateRange[1]):'No dated rows'} · exported ${new Date(preview.exportedAt).toLocaleDateString('en-AU')}</p><div class="jr-preview-counts">${[['weights','Weigh-ins'],['sessions','MASS sessions']].map(([key,label])=>`<div><strong>${label}</strong><dl>${[['added','New'],['updated','Updated'],['deleted','Deletion markers'],['unchanged','Unchanged'],['older','Older versions skipped']].map(([field,title])=>`<div><dt>${title}</dt><dd>${count(key)[field]}</dd></div>`).join('')}</dl></div>`).join('')}</div><p>After import: ${preview.result.weights} active weight readings and ${preview.result.sessions} active logged sessions. Missing rows in this file will not delete existing history.</p><p class="jr-section-note">Only weight and session records enter the journal. The original file is kept privately for backup.</p>${message?`<p role="alert" class="tr-error">${escape(message)}</p>`:''}<button class="primary-button" id="commit-import" ${busy?'disabled':''}>${busy?'Saving your history…':'Import records'}</button><button class="text-button" id="cancel-import" ${busy?'disabled':''}>Cancel</button>`;document.querySelector('#commit-import').addEventListener('click',commitImport);document.querySelector('#cancel-import').addEventListener('click',closeReview);document.querySelector('#close-review').disabled=busy;}
function closeReview(){if(busy)return;document.querySelector('#mass-review').close();preview=null;document.querySelector('#choose-file')?.focus();}
async function commitImport(){if(busy||!preview)return;busy=true;renderReview();try{const result=await api('/api/mass/commit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:preview.token})});document.querySelector('#mass-review').close();busy=false;preview=null;await load(windowChoice);const changed=Object.values(result.counts).reduce((n,c)=>n+c.added+c.updated+c.deleted,0);document.querySelector('#import-status').textContent=changed?'MASS history saved on this computer.':'Already up to date. No duplicate records added.';document.querySelector('#choose-file').focus({preventScroll:true});}catch(e){busy=false;if(preview)renderReview(e.message);else error(e.message);}}
try{await load();}catch(e){root.innerHTML=`<main class="training-loading"><h1>Your journal couldn’t load.</h1><p>${escape(e.message)}</p><button class="primary-button" id="retry">Retry</button><a href="/training" class="text-button">Back to training</a></main>`;document.querySelector('#retry').addEventListener('click',()=>location.reload());}
